import{_ as a,o as e,c as d,a3 as n}from"./chunks/framework.B49jkbEp.js";const b=JSON.parse('{"title":"Layer 1: 锚点识别","description":"","frontmatter":{},"headers":[],"relativePath":"layer1.md","filePath":"layer1.md","lastUpdated":1791637873000}'),s={name:"layer1.md"};function r(o,t,l,c,p,i){return e(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="layer-1-锚点识别" tabindex="-1">Layer 1: 锚点识别 <a class="header-anchor" href="#layer-1-锚点识别" aria-label="Permalink to &quot;Layer 1: 锚点识别&quot;">​</a></h1><p>Layer 1 是 AgentSAST 漏斗的第一层，职责是 <strong>高召回率地识别潜在漏洞锚点</strong>。它的设计哲学是&quot;宁报勿漏&quot;——宁可多报误报，也不能漏掉真正的漏洞。误报的过滤交给 L2 和 L3 完成。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源代码</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├──→ Semgrep 扫描器 ──→ SARIF ──→ Anchor[]</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├──→ Flawfinder 扫描器 ──→ SARIF ──→ Anchor[]</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └──→ (Flawfinder 不可用时)</span></span>
<span class="line"><span>       内置模式扫描器 ──→ Anchor[]</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>         scanner.py 统一入口</span></span>
<span class="line"><span>         去重: (tool, file, line) 三元组</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>            Anchor[]</span></span></code></pre></div><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>文件</th><th>职责</th></tr></thead><tbody><tr><td>数据模型</td><td><code>layer1/models.py</code></td><td><code>Anchor</code>, <code>Location</code>, <code>Severity</code> 定义</td></tr><tr><td>统一入口</td><td><code>layer1/scanner.py</code></td><td>并行调度扫描器 + SARIF 通用解析 + 去重</td></tr><tr><td>Semgrep</td><td><code>layer1/semgrep.py</code></td><td>调用 Semgrep CLI + 解析 SARIF 输出</td></tr><tr><td>Flawfinder</td><td><code>layer1/flawfinder.py</code></td><td>调用 Flawfinder CLI + 内置模式扫描器后备</td></tr></tbody></table><h2 id="去重策略" tabindex="-1">去重策略 <a class="header-anchor" href="#去重策略" aria-label="Permalink to &quot;去重策略&quot;">​</a></h2><p>多个扫描器可能报告同一位置的同一问题。去重基于 <code>(tool, file, line)</code> 三元组：</p><ul><li>同一工具、同一文件、同一行 → 只保留第一个</li><li>不同工具报告同一行 → 都保留（不同工具视角互补）</li></ul><h2 id="sarif-v2-1-0-统一格式" tabindex="-1">SARIF v2.1.0 统一格式 <a class="header-anchor" href="#sarif-v2-1-0-统一格式" aria-label="Permalink to &quot;SARIF v2.1.0 统一格式&quot;">​</a></h2><p>所有 L1 扫描器最终产出 SARIF v2.1.0 格式的结果，这是 OASIS 标准，便于与 GitHub Code Scanning、VS Code 等生态集成。SARIF 核心字段映射：</p><table tabindex="0"><thead><tr><th>SARIF 字段</th><th>Anchor 字段</th><th>说明</th></tr></thead><tbody><tr><td><code>ruleId</code></td><td><code>rule_id</code></td><td>规则 ID</td></tr><tr><td><code>level</code></td><td><code>severity</code></td><td>严重等级</td></tr><tr><td><code>message.text</code></td><td><code>message</code></td><td>告警描述</td></tr><tr><td><code>locations[0].physicalLocation</code></td><td><code>location</code></td><td>文件+行列号</td></tr><tr><td><code>properties.tags</code> (CWE-*)</td><td><code>cwe</code></td><td>CWE 编号</td></tr><tr><td>—</td><td><code>sink_function</code></td><td>危险函数名 (从消息提取)</td></tr><tr><td>—</td><td><code>sink_params</code></td><td>数据流参数 (从 codeFlows 提取)</td></tr></tbody></table><h2 id="内置模式扫描器" tabindex="-1">内置模式扫描器 <a class="header-anchor" href="#内置模式扫描器" aria-label="Permalink to &quot;内置模式扫描器&quot;">​</a></h2><p>当 Flawfinder 未安装时，自动启用内置模式扫描器。它维护了一个 23 项的危险函数→CWE 映射表：</p><table tabindex="0"><thead><tr><th>函数族</th><th>CWE</th><th>典型函数</th></tr></thead><tbody><tr><td>缓冲区溢出</td><td>CWE-120</td><td>memcpy, strcpy, strcat, gets, sprintf, scanf, vsprintf</td></tr><tr><td>堆溢出</td><td>CWE-787</td><td>malloc, realloc</td></tr><tr><td>双重释放</td><td>CWE-415</td><td>free</td></tr><tr><td>命令注入</td><td>CWE-78</td><td>system, popen, execl/execle/execlp/execv/execve/execvp</td></tr><tr><td>格式化字符串</td><td>CWE-134</td><td>printf, fprintf, syslog</td></tr></tbody></table><p>这个扫描器本质上是正则级别（<code>\\b(func_name)\\s*\\(</code>），没有数据流分析，因此误报率很高——但这正是 L2+L3 存在的意义。</p>`,16)])])}const f=a(s,[["render",r]]);export{b as __pageData,f as default};
